  const order = Array.from(new Set(vseed.dataset.map((d) => d[vseed?.page.field])))

  // Status player
  const [currentIndex, setCurrentIndex] = useState(() => {
    const idx = order.indexOf(vseed?.page?.currentValue)
    return idx === -1 ? 0 : idx
  })
  const [current, setCurrent] = useState(order[currentIndex])
  const [isPlaying, setIsPlaying] = useState(false)

  // Sinkronkan nilai current
  useEffect(() => {
    setCurrent(order[currentIndex])
  }, [currentIndex])

  // Logika putar otomatis
  useEffect(() => {
    let timer: number
    if (isPlaying) {
      timer = window.setInterval(() => {
        setCurrentIndex((prev) => (prev + 1) % order.length)
      }, 1000)
    }
    return () => clearInterval(timer)
  }, [isPlaying, order.length])

  // Penanganan event
  const handlePrev = () => setCurrentIndex((prev) => (prev - 1 + order.length) % order.length)
  const handleNext = () => setCurrentIndex((prev) => (prev + 1) % order.length)
  const togglePlay = () => setIsPlaying(!isPlaying)

  const tableRef = useRef(null)
  const chartRef = useRef(null)
  useEffect(() => {
    if (!ref.current) {
      return
    }

    const seed: VSeed = {
      ...vseed,
      page: {
        ...(vseed?.page || {}),
        currentValue: current,
      },
    }

    const builder = Builder.from(seed)
    const spec = builder.build()
    console.log(spec)
    if (isTable(seed)) {
      if (tableRef.current) {
        tableRef.current.updateOption(spec)
      } else {
        tableRef.current = new ListTable(ref.current, spec)
      }
    } else if (isPivotTable(seed)) {
      if (tableRef.current) {
        tableRef.current.updateOption(spec)
      } else {
        tableRef.current = new PivotTable(ref.current, spec)
      }
    } else {
      if (chartRef.current) {
        chartRef.current.updateSpec(spec)
      } else {
        chartRef.current = new VChart(spec, { dom: ref.current })
        chartRef.current.renderSync()
      }
    }
  }, [current])

  const btnStyle = {
    border: '1px solid #e2e8f0',
    background: '#fff',
    borderRadius: '6px',
    height: '32px',
    padding: '0 12px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '14px',
    transition: 'all 0.2s',
    color: '#333',
  }

  const iconStyle = {
    width: 16,
    height: 16,
    fill: 'currentColor',
  }

  return (
    <div style={{ fontFamily: 'sans-serif' }}>
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 12,
          marginBottom: 16,
          padding: 16,
          border: '1px solid #eee',
          borderRadius: 8,
          background: '#f8fafc',
        }}
      >
        {/* Baris 1: Kontrol player */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <button onClick={handlePrev} style={btnStyle} title="Sebelumnya">
            <svg viewBox="0 0 24 24" style={iconStyle}>
              <path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z" />
            </svg>
          </button>

          <select
            style={{
              flex: 1,
              height: '32px',
              border: '1px solid #e2e8f0',
              borderRadius: '6px',
              padding: '0 8px',
              outline: 'none',
            }}
            value={currentIndex}
            onChange={(e) => setCurrentIndex(Number(e.target.value))}
          >
            {order.map((d, i) => (
              <option key={i} value={i}>
                {d}
              </option>
            ))}
          </select>

          <button onClick={handleNext} style={btnStyle} title="Berikutnya">
            <svg viewBox="0 0 24 24" style={iconStyle}>
              <path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z" />
            </svg>
          </button>

          <button onClick={togglePlay} style={{ ...btnStyle, minWidth: 80 }} title={isPlaying ? 'Pause' : 'Play'}>
            {isPlaying ? (
              <>
                <svg viewBox="0 0 24 24" style={{ ...iconStyle, marginRight: 4 }}>
                  <path d="M6 19h4V5H6v14zm8-14v14h4V5h-4z" />
                </svg>
                Pause
              </>
            ) : (
              <>
                <svg viewBox="0 0 24 24" style={{ ...iconStyle, marginRight: 4 }}>
                  <path d="M8 5v14l11-7z" />
                </svg>
                Play
              </>
            )}
          </button>
        </div>

        {/* Baris 2: Bilah progres */}
        <div style={{ display: 'flex', alignItems: 'center' }}>
          <input
            type="range"
            min="0"
            max={order.length - 1}
            value={currentIndex}
            onChange={(e) => setCurrentIndex(Number(e.target.value))}
            style={{ width: '100%', cursor: 'pointer' }}
          />
        </div>
      </div>
      <div ref={ref} style={{ height: 260, width: '100%' }} />
    </div>
  )
